# Reference port-placement algorithms for Logisim 2.7.1 std components.
# Each `ports_*` function receives `a`: dict attr-name -> parsed value
# (defaults already applied; see components_271.json "attributes"), and
# returns a list of ports: dict(name, dir, width, dx, dy) where (dx, dy)
# is the offset from the component's `loc`. dir is from the component's
# point of view: "input" (component reads), "output" (component drives),
# "inout". width is an int or None (= adapts to whatever is attached).
# Integer division in Java truncates toward zero -> use jdiv().

# ---------------------------------------------------------------- helpers
DEG = {"east": 0, "north": 90, "west": 180, "south": 270}


def jdiv(a, b):
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b >= 0) else -q


def P(name, dir, width, dx, dy):
    return {"name": name, "dir": dir, "width": width, "dx": dx, "dy": dy}


def translate(x, y, d, dist, right=0):
    # data/Location.translate(Direction, int dist, int right)
    if d == "east":
        return (x + dist, y + right)
    if d == "west":
        return (x - dist, y - right)
    if d == "south":
        return (x - right, y + dist)
    if d == "north":
        return (x + right, y - dist)
    return (x + dist, y + right)


def rotate_pt(x, y, frm, to):
    # data/Location.rotate(from, to, 0, 0)
    deg = (DEG[to] - DEG[frm]) % 360
    if deg == 90:
        return (y, -x)
    if deg == 180:
        return (-x, -y)
    if deg == 270:
        return (-y, x)
    return (x, y)


def reverse(d):
    return {"east": "west", "west": "east", "north": "south", "south": "north"}[d]


# ---------------------------------------------------------------- #Gates
def ports_abstract_gate(a, bonus_width, negate_output):
    # std/gates/AbstractGate.computePorts + getInputOffset
    inputs = a["inputs"]
    facing = a["facing"]
    size = int(a["size"])
    w = a["width"]
    axis = size + bonus_width + (10 if negate_output else 0)
    if inputs <= 3:
        if size < 40:
            skip_start, skip_dist, skip_lower_even = -5, 10, 10
        elif size < 60 or inputs <= 2:
            skip_start, skip_dist, skip_lower_even = -10, 20, 20
        else:
            skip_start, skip_dist, skip_lower_even = -15, 30, 30
    elif inputs == 4 and size >= 60:
        skip_start, skip_dist, skip_lower_even = -5, 20, 0
    else:
        skip_start, skip_dist, skip_lower_even = -5, 10, 10
    ports = [P("out", "output", w, 0, 0)]
    for i in range(inputs):
        if inputs % 2 == 1:
            dy = skip_start * (inputs - 1) + skip_dist * i
        else:
            dy = skip_start * inputs + skip_dist * i
            if i >= jdiv(inputs, 2):
                dy += skip_lower_even
        dx = axis + (10 if a.get("negate%d" % i, False) else 0)
        if facing == "north":
            x, y = dy, dx
        elif facing == "south":
            x, y = dy, -dx
        elif facing == "west":
            x, y = dx, dy
        else:
            x, y = -dx, dy
        ports.append(P("in%d" % i, "input", w, x, y))
    return ports


def ports_not_gate(a):
    # std/gates/NotGate.configurePorts
    dx = -20 if a["size"] == "20" else -30
    x, y = translate(0, 0, a["facing"], dx)
    return [P("out", "output", a["width"], 0, 0), P("in", "input", a["width"], x, y)]


def ports_buffer(a):
    # std/gates/Buffer.configurePorts
    x, y = translate(0, 0, a["facing"], -20)
    return [P("out", "output", a["width"], 0, 0), P("in", "input", a["width"], x, y)]


def ports_controlled(a, is_inverter):
    # std/gates/ControlledBuffer.configurePorts (+ getOffsetBounds)
    w = 20
    if is_inverter and a.get("size", "30") != "20":
        w = 30
    d = max(w, 20) - 20
    rev = reverse(a["facing"])
    x1, y1 = translate(0, 0, rev, 20 + d)
    if a["control"] == "left":
        x2, y2 = translate(0, 0, rev, 10 + d, 10)
    else:
        x2, y2 = translate(0, 0, rev, 10 + d, -10)
    return [P("out", "output", a["width"], 0, 0),
            P("in", "input", a["width"], x1, y1),
            P("control", "input", 1, x2, y2)]


# ---------------------------------------------------------------- #Wiring
def splitter_distribution(fanout, bits):
    # circuit/SplitterAttributes.computeDistribution(fanout, bits, 1)
    ret = [0] * bits
    if fanout >= bits:
        for i in range(bits):
            ret[i] = i + 1
    else:
        threads_per_end = jdiv(bits, fanout)
        ends_with_extra = bits % fanout
        cur_end = -1
        left_in_end = 0
        for i in range(bits):
            if left_in_end == 0:
                cur_end += 1
                left_in_end = threads_per_end
                if ends_with_extra > 0:
                    left_in_end += 1
                    ends_with_extra -= 1
            ret[i] = 1 + cur_end
            left_in_end -= 1
    return ret


def splitter_bit_end(a):
    # bit_end[i]: 0 = bit not connected to any split end, k = split end k (1-based).
    # XML "bitN": "none" -> 0, "k" -> k+1. Missing bitN -> XmlReader applies the
    # factory default N+1, which SplitterAttributes.setValue accepts only if N+1 <= fanout;
    # otherwise the computeDistribution() value stays.
    fanout = a["fanout"]
    bits = a["incoming"]
    dist = splitter_distribution(fanout, bits)
    out = []
    for i in range(bits):
        raw = a.get("bit%d" % i)
        if raw is None:
            v = i + 1 if i + 1 <= fanout else dist[i]
        else:
            v = raw if 0 <= raw <= fanout else dist[i]
        out.append(v)
    return out


def ports_splitter(a):
    # circuit/SplitterParameters + Splitter.configureComponent
    fanout = a["fanout"]
    facing = a["facing"]
    appear = a["appear"]
    if appear in ("center", "legacy"):
        justify = 0
    elif appear == "right":
        justify = 1
    else:
        justify = -1
    width = 20
    if facing in ("north", "south"):
        m = 1 if facing == "north" else -1
        if justify == 0:
            dx0 = 10 * (jdiv(fanout + 1, 2) - 1)
        elif m * justify < 0:
            dx0 = -10
        else:
            dx0 = 10 * fanout
        dy0 = -m * width
        ddx, ddy = -10, 0
    else:
        m = -1 if facing == "west" else 1
        dx0 = m * width
        if justify == 0:
            dy0 = -10 * jdiv(fanout, 2)
        elif m * justify > 0:
            dy0 = 10
        else:
            dy0 = -10 * fanout
        ddx, ddy = 0, 10
    bit_end = splitter_bit_end(a)
    widths = [0] * (fanout + 1)
    for e in bit_end:
        if e > 0:
            widths[e] += 1
    ports = [P("combined", "inout", a["incoming"], 0, 0)]
    x, y = dx0, dy0
    for i in range(fanout):
        ports.append(P("end%d" % i, "inout", widths[i + 1] if widths[i + 1] > 0 else None, x, y))
        x += ddx
        y += ddy
    return ports


def ports_pin(a):
    # std/wiring/Pin.configurePorts: output pin -> port is INPUT, input pin -> OUTPUT
    if a["output"]:
        return [P("pin", "input", a["width"], 0, 0)]
    return [P("pin", "output", a["width"], 0, 0)]


def ports_probe(a):
    return [P("in", "input", None, 0, 0)]


def ports_tunnel(a):
    return [P("io", "inout", a["width"], 0, 0)]


def ports_pull_resistor(a):
    return [P("io", "inout", None, 0, 0)]


def ports_clock(a):
    return [P("out", "output", 1, 0, 0)]


def ports_constant(a):
    return [P("out", "output", a["width"], 0, 0)]


def ports_power_ground(a):
    return [P("out", "output", a["width"], 0, 0)]


def _trans_d(facing):
    dx = dy = 0
    if facing == "north":
        dy = 1
    elif facing == "east":
        dx = -1
    elif facing == "south":
        dy = -1
    elif facing == "west":
        dx = 1
    return dx, dy


def ports_transistor(a):
    # std/wiring/Transistor.updatePorts
    facing = a["facing"]
    dx, dy = _trans_d(facing)
    flip = (facing in ("south", "west")) == (a["gate"] == "tl")
    if flip:
        g = (20 * (dx + dy), 20 * (-dx + dy))
    else:
        g = (20 * (dx - dy), 20 * (dx + dy))
    return [P("out", "output", a["width"], 0, 0),
            P("in", "input", a["width"], 40 * dx, 40 * dy),
            P("gate", "input", 1, g[0], g[1])]


def ports_transmission_gate(a):
    # std/wiring/TransmissionGate.updatePorts
    facing = a["facing"]
    dx, dy = _trans_d(facing)
    flip = (facing in ("south", "west")) == (a["gate"] == "tl")
    pa = (20 * (dx - dy), 20 * (dx + dy))
    pb = (20 * (dx + dy), 20 * (-dx + dy))
    if flip:
        g1, g0 = pa, pb
    else:
        g0, g1 = pa, pb
    return [P("out", "output", a["width"], 0, 0),
            P("in", "input", a["width"], 40 * dx, 40 * dy),
            P("gate0", "input", 1, g0[0], g0[1]),
            P("gate1", "input", 1, g1[0], g1[1])]


def ports_bit_extender(a):
    # std/wiring/BitExtender.configurePorts (no facing; fixed geometry)
    ps = [P("out", "output", a["out_width"], 0, 0),
          P("in", "input", a["in_width"], -40, 0)]
    if a["type"] == "input":
        ps.append(P("extend", "input", 1, -20, -20))
    return ps


# ---------------------------------------------------------------- #Plexers
def ports_multiplexer(a):
    # std/plexers/Multiplexer.updatePorts
    d = a["facing"]
    sel_mult = 1 if a["selloc"] == "bl" else -1
    data = a["width"]
    sbits = a["select"]
    enable = a["enable"]
    inputs = 1 << sbits
    ps = []
    if inputs == 2:
        if d == "west":
            e0, e1, sel = (30, -10), (30, 10), (20, sel_mult * 20)
        elif d == "north":
            e0, e1, sel = (-10, 30), (10, 30), (sel_mult * -20, 20)
        elif d == "south":
            e0, e1, sel = (-10, -30), (10, -30), (sel_mult * -20, -20)
        else:
            e0, e1, sel = (-30, -10), (-30, 10), (-20, sel_mult * 20)
        ps.append(P("in0", "input", data, e0[0], e0[1]))
        ps.append(P("in1", "input", data, e1[0], e1[1]))
    else:
        dx = -jdiv(inputs, 2) * 10
        ddx = 10
        dy = -jdiv(inputs, 2) * 10
        ddy = 10
        if d == "west":
            dx, ddx = 40, 0
            sel = (20, sel_mult * (dy + 10 * inputs))
        elif d == "north":
            dy, ddy = 40, 0
            sel = (sel_mult * dx, 20)
        elif d == "south":
            dy, ddy = -40, 0
            sel = (sel_mult * dx, -20)
        else:
            dx, ddx = -40, 0
            sel = (-20, sel_mult * (dy + 10 * inputs))
        for i in range(inputs):
            ps.append(P("in%d" % i, "input", data, dx, dy))
            dx += ddx
            dy += ddy
    ps.append(P("select", "input", sbits, sel[0], sel[1]))
    if enable:
        en = translate(sel[0], sel[1], d, 10)
        ps.append(P("enable", "input", 1, en[0], en[1]))
    ps.append(P("out", "output", data, 0, 0))
    return ps


def ports_demultiplexer(a):
    # std/plexers/Demultiplexer.updatePorts
    d = a["facing"]
    sel_mult = 1 if a["selloc"] == "bl" else -1
    data = a["width"]
    sbits = a["select"]
    enable = a["enable"]
    outputs = 1 << sbits
    ps = []
    if outputs == 2:
        if d == "west":
            e0, e1, sel = (-30, -10), (-30, 10), (-20, sel_mult * 20)
        elif d == "north":
            e0, e1, sel = (-10, -30), (10, -30), (sel_mult * -20, -20)
        elif d == "south":
            e0, e1, sel = (-10, 30), (10, 30), (sel_mult * -20, 20)
        else:
            e0, e1, sel = (30, -10), (30, 10), (20, sel_mult * 20)
        ps.append(P("out0", "output", data, e0[0], e0[1]))
        ps.append(P("out1", "output", data, e1[0], e1[1]))
    else:
        dx = -jdiv(outputs, 2) * 10
        ddx = 10
        dy = dx
        ddy = 10
        if d == "west":
            dx, ddx = -40, 0
            sel = (-20, sel_mult * (dy + 10 * outputs))
        elif d == "north":
            dy, ddy = -40, 0
            sel = (sel_mult * dx, -20)
        elif d == "south":
            dy, ddy = 40, 0
            sel = (sel_mult * dx, 20)
        else:
            dx, ddx = 40, 0
            sel = (20, sel_mult * (dy + 10 * outputs))
        for i in range(outputs):
            ps.append(P("out%d" % i, "output", data, dx, dy))
            dx += ddx
            dy += ddy
    ps.append(P("select", "input", sbits, sel[0], sel[1]))
    if enable:
        en = translate(sel[0], sel[1], d, -10)
        ps.append(P("enable", "input", 1, en[0], en[1]))
    ps.append(P("in", "input", data, 0, 0))
    return ps


def ports_decoder(a):
    # std/plexers/Decoder.updatePorts
    d = a["facing"]
    tr = a["selloc"] == "tr"
    sbits = a["select"]
    enable = a["enable"]
    outputs = 1 << sbits
    ps = []
    if outputs == 2:
        if d in ("north", "south"):
            y = -10 if d == "north" else 10
            e0, e1 = ((-30, y), (-10, y)) if tr else ((10, y), (30, y))
        else:
            x = -10 if d == "west" else 10
            e0, e1 = ((x, 10), (x, 30)) if tr else ((x, -30), (x, -10))
        ps.append(P("out0", "output", 1, e0[0], e0[1]))
        ps.append(P("out1", "output", 1, e1[0], e1[1]))
    else:
        if d in ("north", "south"):
            dy = -20 if d == "north" else 20
            ddy = 0
            dx = -10 * outputs if tr else 0
            ddx = 10
        else:
            dx = -20 if d == "west" else 20
            ddx = 0
            dy = 0 if tr else -10 * outputs
            ddy = 10
        for i in range(outputs):
            ps.append(P("out%d" % i, "output", 1, dx, dy))
            dx += ddx
            dy += ddy
    ps.append(P("select", "input", sbits, 0, 0))
    if enable:
        en = translate(0, 0, d, -10)
        ps.append(P("enable", "input", 1, en[0], en[1]))
    return ps


def ports_priority_encoder(a):
    # std/plexers/PriorityEncoder.updatePorts ; port order: in0..in(n-1), out, enable_in, enable_out, group_signal
    d = a["facing"]
    sbits = a["select"]
    n = 1 << sbits
    ps = []
    if d in ("north", "south"):
        x = -5 * n + 10
        y = 40 if d == "north" else -40
        for i in range(n):
            ps.append(P("in%d" % i, "input", 1, x + 10 * i, y))
        ps.append(P("out", "output", sbits, 0, 0))
        ps.append(P("enable_in", "input", 1, x + 10 * n, jdiv(y, 2)))
        ps.append(P("enable_out", "output", 1, x - 10, jdiv(y, 2)))
        ps.append(P("group_signal", "output", 1, 10, 0))
    else:
        x = -40 if d == "east" else 40
        y = -5 * n + 10
        for i in range(n):
            ps.append(P("in%d" % i, "input", 1, x, y + 10 * i))
        ps.append(P("out", "output", sbits, 0, 0))
        ps.append(P("enable_in", "input", 1, jdiv(x, 2), y + 10 * n))
        ps.append(P("enable_out", "output", 1, jdiv(x, 2), y - 10))
        ps.append(P("group_signal", "output", 1, 0, 10))
    return ps


def ports_bit_selector(a):
    # std/plexers/BitSelector.updatePorts
    d = a["facing"]
    data = a["width"]
    group = a["group"]
    groups = jdiv(data + group - 1, group) - 1
    select_bits = 1
    if groups > 0:
        while groups != 1:
            groups >>= 1
            select_bits += 1
    if d == "west":
        inp, sel = (30, 0), (10, 10)
    elif d == "north":
        inp, sel = (0, 30), (-10, 10)
    elif d == "south":
        inp, sel = (0, -30), (-10, -10)
    else:
        inp, sel = (-30, 0), (-10, 10)
    return [P("out", "output", group, 0, 0),
            P("in", "input", data, inp[0], inp[1]),
            P("select", "input", select_bits, sel[0], sel[1])]


# ---------------------------------------------------------------- #Arithmetic
def ports_adder(a):
    w = a["width"]
    # NB: carry-out is declared Port.INPUT in Adder.java (source quirk) but is driven by propagate()
    return [P("a", "input", w, -40, -10), P("b", "input", w, -40, 10), P("out", "output", w, 0, 0),
            P("carry_in", "input", 1, -20, -20), P("carry_out", "output", 1, -20, 20)]


def ports_subtractor(a):
    w = a["width"]
    return [P("a", "input", w, -40, -10), P("b", "input", w, -40, 10), P("out", "output", w, 0, 0),
            P("borrow_in", "input", 1, -20, -20), P("borrow_out", "output", 1, -20, 20)]


def ports_multiplier(a):
    w = a["width"]
    return [P("a", "input", w, -40, -10), P("b", "input", w, -40, 10), P("out", "output", w, 0, 0),
            P("carry_in", "input", w, -20, -20), P("carry_out", "output", w, -20, 20)]


def ports_divider(a):
    w = a["width"]
    return [P("dividend_lower", "input", w, -40, -10), P("divisor", "input", w, -40, 10),
            P("quotient", "output", w, 0, 0), P("dividend_upper", "input", w, -20, -20),
            P("remainder", "output", w, -20, 20)]


def ports_negator(a):
    w = a["width"]
    return [P("in", "input", w, -40, 0), P("out", "output", w, 0, 0)]


def ports_comparator(a):
    w = a["width"]
    return [P("a", "input", w, -40, -10), P("b", "input", w, -40, 10),
            P("gt", "output", 1, 0, -10), P("eq", "output", 1, 0, 0), P("lt", "output", 1, 0, 10)]


def ports_shifter(a):
    data = a["width"]
    shift = 1
    while (1 << shift) < data:
        shift += 1
    return [P("data", "input", data, -40, -10), P("dist", "input", shift, -40, 10),
            P("out", "output", data, 0, 0)]


def ports_bit_adder(a):
    w = a["width"]
    inputs = a["inputs"]
    max_bits = w * inputs
    out_w = 1
    while (1 << out_w) <= max_bits:
        out_w += 1
    dy = 10
    if inputs == 1:
        y = 0
    elif inputs == 2:
        y, dy = -10, 20
    elif inputs == 3:
        y = -10
    else:
        y = jdiv(inputs - 1, 2) * -10
    ps = [P("out", "output", out_w, 0, 0)]
    for i in range(inputs):
        ps.append(P("in%d" % i, "input", w, -40, y + i * dy))
    return ps


def ports_bit_finder(a):
    w = a["width"]
    max_bits = w - 1
    out_w = 1
    while (1 << out_w) <= max_bits:
        out_w += 1
    return [P("present", "output", 1, -20, 20), P("index", "output", out_w, 0, 0),
            P("in", "input", w, -40, 0)]


# ---------------------------------------------------------------- #Memory
def ports_flip_flop(a, input_names):
    # std/memory/AbstractFlipFlop constructor. Order: data inputs, clock, Q, notQ, reset, preset, enable
    if len(input_names) == 1:
        ps = [P(input_names[0], "input", 1, -40, 20), P("clock", "input", 1, -40, 0)]
    else:
        ps = [P(input_names[0], "input", 1, -40, 0), P(input_names[1], "input", 1, -40, 20),
              P("clock", "input", 1, -40, 10)]
    ps += [P("q", "output", 1, 0, 0), P("nq", "output", 1, 0, 20),
           P("reset", "input", 1, -10, 30), P("preset", "input", 1, -30, 30),
           P("enable", "input", 1, -20, 30)]
    return ps


def ports_register(a):
    w = a["width"]
    return [P("q", "output", w, 0, 0), P("d", "input", w, -30, 0), P("clock", "input", 1, -20, 20),
            P("clear", "input", 1, -10, 20), P("enable", "input", 1, -30, 10)]


def ports_counter(a):
    w = a["width"]
    return [P("q", "output", w, 0, 0), P("d", "input", w, -30, 0), P("clock", "input", 1, -20, 20),
            P("clear", "input", 1, -10, 20), P("load", "input", 1, -30, -10),
            P("count", "input", 1, -30, 10), P("carry", "output", 1, 0, 10)]


def ports_shift_register(a):
    # std/memory/ShiftRegister.configurePorts (location = left edge; no facing)
    w = a["width"]
    parallel = a["parallel"]
    length = a["length"]
    bw = 20 + 10 * length if parallel else 30
    ps = [P("in", "input", w, 0, 0), P("shift", "input", 1, 0, -10), P("clock", "input", 1, 0, 10),
          P("clear", "input", 1, 10, 20), P("out", "output", w, bw, 0)]
    if parallel:
        ps.append(P("load", "input", 1, 10, -20))
        for i in range(length):
            ps.append(P("d%d" % i, "input", w, 20 + 10 * i, -20))
            ps.append(P("q%d" % i, "output", w, 20 + 10 * i, 20))
    return ps


def ports_random(a):
    w = a["width"]
    return [P("q", "output", w, 0, 0), P("clock", "input", 1, -30, -10),
            P("next", "input", 1, -30, 10), P("reset", "input", 1, -20, 20)]


def ports_ram(a):
    # std/memory/Mem.configureStandardPorts + Ram.configurePorts
    bus = a["bus"]
    ps = [P("data", "inout", a["dataWidth"], 0, 0), P("addr", "input", a["addrWidth"], -140, 0),
          P("cs", "input", 1, -90, 40), P("oe", "input", 1, -50, 40), P("clear", "input", 1, -30, 40)]
    if bus != "asynch":
        ps.append(P("clock", "input", 1, -70, 40))
    if bus == "separate":
        ps.append(P("we", "input", 1, -110, 40))
        ps.append(P("din", "input", a["dataWidth"], -140, 20))
    return ps


def ports_rom(a):
    # DATA declared INOUT in Mem.configureStandardPorts; ROM only drives it.
    return [P("data", "inout", a["dataWidth"], 0, 0), P("addr", "input", a["addrWidth"], -140, 0),
            P("cs", "input", 1, -90, 40)]


# ---------------------------------------------------------------- #I/O
def ports_button(a):
    return [P("out", "output", 1, 0, 0)]


def ports_led(a):
    return [P("in", "input", 1, 0, 0)]


def ports_joystick(a):
    return [P("x", "output", a["bits"], 0, 0), P("y", "output", a["bits"], 0, 10)]


def ports_keyboard(a):
