# ---------------------------------------------------------------- subcircuits
def _compute_dimension(max_this, max_others):
    if max_this < 3:
        return 30
    if max_others == 0:
        return 10 * max_this
    return 10 * max_this + 10


def _compute_offset(num_facing, num_opposite, max_others):
    max_this = max(num_facing, num_opposite)
    if max_this in (0, 1):
        max_offs = 15 if max_others == 0 else 10
    elif max_this == 2:
        max_offs = 10
    else:
        max_offs = 5 if max_others == 0 else 10
    return max_offs + 10 * jdiv(max_this - num_facing, 2)


def default_appearance(pins):
    """circuit/appear/DefaultAppearance.build.
    pins: list of dict(x, y, facing, output(bool), width, label) for every Pin in the subcircuit.
    Returns (anchor_facing, [(pin, ox, oy)]) with (ox, oy) relative to the anchor
    (= the instance loc), for an instance whose facing equals anchor_facing (east)."""
    edge = {"north": [], "south": [], "east": [], "west": []}
    for p in pins:
        edge[reverse(p["facing"])].append(p)
    for k, lst in edge.items():
        if k in ("north", "south"):
            lst.sort(key=lambda p: (p["x"], p["x"], p["y"]))
        else:
            lst.sort(key=lambda p: (p["y"], p["x"], p["y"]))
    n_n, n_s, n_e, n_w = (len(edge[k]) for k in ("north", "south", "east", "west"))
    max_vert = max(n_n, n_s)
    max_horz = max(n_e, n_w)
    offs_n = _compute_offset(n_n, n_s, max_horz)
    offs_s = _compute_offset(n_s, n_n, max_horz)
    offs_e = _compute_offset(n_e, n_w, max_vert)
    offs_w = _compute_offset(n_w, n_e, max_vert)
    width = _compute_dimension(max_vert, max_horz)
    height = _compute_dimension(max_horz, max_vert)
    if n_e > 0:
        ax, ay = width, offs_e
    elif n_n > 0:
        ax, ay = offs_n, 0
    elif n_w > 0:
        ax, ay = 0, offs_w
    elif n_s > 0:
        ax, ay = offs_s, height
    else:
        ax, ay = 0, 0
    out = []
    for i, p in enumerate(edge["west"]):
        out.append((p, 0 - ax, offs_w + 10 * i - ay))
    for i, p in enumerate(edge["east"]):
        out.append((p, width - ax, offs_e + 10 * i - ay))
    for i, p in enumerate(edge["north"]):
        out.append((p, offs_n + 10 * i - ax, 0 - ay))
    for i, p in enumerate(edge["south"]):
        out.append((p, offs_s + 10 * i - ax, height - ay))
    return "east", out


def ports_subcircuit(a, pins, custom_appearance=None):
    """SubcircuitFactory.computePorts + CircuitAppearance.getPortOffsets.
    custom_appearance: None for default appearance, else dict(anchor=(x,y) or None,
    anchor_facing=str, ports=[(pin_x, pin_y, px, py)]) where (px,py) = round(x+w/2), round(y+h/2)
    of each <circ-port> and (pin_x,pin_y) its "pin" attribute (location of the Pin in the subcircuit)."""
    if custom_appearance is None:
        anchor_facing, offs = default_appearance(pins)
    else:
        by_loc = {(p["x"], p["y"]): p for p in pins}
        anchor = custom_appearance.get("anchor")
        anchor_facing = custom_appearance.get("anchor_facing", "east")
        offs = []
        for (pinx, piny, px, py) in custom_appearance["ports"]:
            p = by_loc.get((pinx, piny))
            if p is None:
                continue  # AppearanceSvgReader drops ports whose pin is not found
            if anchor is not None:
                px, py = px - anchor[0], py - anchor[1]
            offs.append((p, px, py))
    facing = a.get("facing") or anchor_facing
    ports = []
    for p, ox, oy in offs:
        if facing != anchor_facing:
            ox, oy = rotate_pt(ox, oy, anchor_facing, facing)
        ports.append(P(p.get("label") or "pin@(%d,%d)" % (p["x"], p["y"]),
                       "output" if p["output"] else "input", p["width"], ox, oy))
    # SubcircuitFactory iterates a TreeMap keyed by Location -> sort by (x, y)
    ports.sort(key=lambda q: (q["dx"], q["dy"]))
    return ports


# ---------------------------------------------------------------- attribute parsing / defaults
def parse_attr_value(atype, raw):
    """Parse the XML string of <a name=.. val=..> (or its text content) like Logisim does."""
    if atype in ("bitwidth",):
        s = raw[1:] if raw.startswith("/") else raw
        return int(s)
    if atype in ("int", "int_range", "duration"):
        return int(raw)
    if atype == "hex_int":
        v = raw.lower()
        if v.startswith("0x"):
            n = int(v[2:], 16)
        elif v.startswith("0b"):
            n = int(v[2:], 2)
        elif v.startswith("0") and len(v) > 1:
            n = int(v[1:], 8)
        else:
            n = int(v, 10)
        n &= 0xFFFFFFFF  # (int) Long.parseLong(...)
        return n - (1 << 32) if n >= (1 << 31) else n
    if atype in ("bool", "negate"):
        return raw.strip().lower() == "true"  # Boolean.valueOf
    if atype == "splitter_bit":
        return 0 if raw == "none" else 1 + int(raw)
    return raw  # direction, option, string, font, color, rom_contents


def version_tuple(source):
    # "2.7.1" -> (2,7,1,0); missing source attribute -> Logisim treats it as 2.7.1
    if not source:
        return (2, 7, 1, 0)
    parts = [int(p) for p in source.split(".")[:4] if p.isdigit()]
    while len(parts) < 4:
        parts.append(0)
    return tuple(parts)


def resolve_attrs(spec, xml_attrs, source_version="2.7.1"):
    """Apply XmlReader.initAttributeSet semantics: every attribute missing from the
    <comp> gets the *factory* default (never the <lib><tool> customisation)."""
    ver = version_tuple(source_version)
    out = {}
    for ad in spec["attributes"]:
        name = ad["name"]
        if ad.get("dynamic") == "negate":
            continue
        if ad.get("dynamic") == "splitter_bits":
            continue
        if name in xml_attrs:
            out[name] = parse_attr_value(ad["type"], xml_attrs[name])
        else:
            dflt = ad["default"]
            vd = ad.get("version_default")
            if vd is not None:
                dflt = vd["new"] if ver >= tuple(vd["since"]) else vd["old"]
            out[name] = None if dflt is None else parse_attr_value(ad["type"], dflt)
    # dynamic attributes
    for ad in spec["attributes"]:
        if ad.get("dynamic") == "negate":
            for i in range(out.get("inputs", 0)):
                k = "negate%d" % i
                out[k] = parse_attr_value("bool", xml_attrs[k]) if k in xml_attrs else False
        elif ad.get("dynamic") == "splitter_bits":
            for i in range(out["incoming"]):
                k = "bit%d" % i
                if k in xml_attrs:
                    out[k] = parse_attr_value("splitter_bit", xml_attrs[k])
    return out
